{
  "$schema": "https://open-design.ai/schemas/plugin.v1.json",
  "specVersion": "1.0.0",
  "name": "example-fs-creative-voltage",
  "title": "Write a Seed Pitch like a Top Pre-Seed Founder",
  "title_i18n": {
    "en": "Write a Seed Pitch like a Top Pre-Seed Founder",
    "zh-CN": "像顶级 pre-seed 创始人一样写种子路演",
    "zh-TW": "像顶级 pre-seed 创始人一样写种子路演"
  },
  "version": "1.0.0",
  "publishedAt": "2026-06-16T09:32:15Z",
  "description": "OpenDesign's seed pitch: the open, local alternative to closed AI design — why now, the wedge, and the ask. Built as a decision-grade fundraising pitch deck for pre-seed & seed VCs.",
  "description_i18n": {
    "en": "OpenDesign's seed pitch: the open, local alternative to closed AI design — why now, the wedge, and the ask. Built as a decision-grade fundraising pitch deck for pre-seed & seed VCs.",
    "zh-CN": "像顶级 pre-seed 创始人一样写种子路演——一份可商业交付的融资路演 Deck，围绕真实主题、证据链与决策目标组织。",
    "zh-TW": "像顶级 pre-seed 创始人一样写种子路演——一份可商业交付的融资路演 Deck，围绕真实主题、证据链与决策目标组织。"
  },
  "license": "MIT",
  "author": {
    "name": "zarazhangrui",
    "url": "https://github.com/zarazhangrui"
  },
  "homepage": "https://github.com/zarazhangrui/frontend-slides",
  "plugin": {
    "repo": "https://github.com/zarazhangrui/frontend-slides"
  },
  "tags": [
    "community",
    "deck",
    "slides",
    "presentation",
    "retro-modern",
    "neon",
    "halftone",
    "web",
    "ppt",
    "launch",
    "campaign",
    "pipeline",
    "marketing",
    "fs-creative-voltage",
    "marketing-and-gtm",
    "fundraising-pitch",
    "series-a-pitch-deck",
    "finance",
    "pitch-deck",
    "fundraising",
    "investor-deck",
    "decision-deck",
    "commercial-slide-agent"
  ],
  "compat": {
    "agentSkills": [
      {
        "path": "./SKILL.md"
      }
    ]
  },
  "od": {
    "kind": "scenario",
    "taskKind": "new-generation",
    "mode": "deck",
    "scenario": "finance",
    "surface": "web",
    "preview": {
      "type": "html",
      "entry": "./example.html",
      "motion": "deck"
    },
    "useCase": {
      "query": {
        "en": "Create \"Write a Seed Pitch like a Top Pre-Seed Founder\" as a decision-grade Fundraising pitch deck in this template's own visual system. Subject: OpenDesign's seed pitch: the open, local alternative to closed AI design — why now, the wedge, and the ask. Audience: pre-seed & seed VCs. First ask only for missing essentials: audience, decision target, source-of-truth materials, deadline, and must-keep numbers. Then produce the slide plan, written slides, visual direction, speaker-ready structure, and a critic pass against this rubric: would an investor know why this is venture-scale and urgent.",
        "zh-CN": "像顶级 pre-seed 创始人一样写种子路演。像顶级 pre-seed 创始人一样写种子路演——一份可商业交付的融资路演 Deck，围绕真实主题、证据链与决策目标组织。 主题：OpenDesign's seed pitch: the open, local alternative to closed AI design — why now, the wedge, and the ask. 先确认受众、决策目标、素材来源、截止时间和必须保留的数据，再输出叙事主线、页面规划、逐页文案、视觉方向和按评审标准自检的版本。"
      },
      "exampleOutputs": [
        {
          "path": "./example.html",
          "title": "Write a Seed Pitch like a Top Pre-Seed Founder",
          "title_i18n": {
            "en": "Write a Seed Pitch like a Top Pre-Seed Founder",
            "zh-CN": "像顶级 pre-seed 创始人一样写种子路演",
            "zh-TW": "像顶级 pre-seed 创始人一样写种子路演"
          }
        }
      ]
    },
    "inputs": [
      {
        "name": "deckType",
        "label": "Deck type",
        "type": "select",
        "required": true,
        "options": [
          "product overview",
          "pitch deck",
          "conference talk",
          "campaign / launch deck",
          "internal presentation"
        ],
        "default": "product overview"
      },
      {
        "name": "topic",
        "label": "Topic",
        "type": "string",
        "required": true,
        "placeholder": "A motion branding toolkit for small teams",
        "default": "the user's brief"
      },
      {
        "name": "audience",
        "label": "Audience",
        "type": "string",
        "required": true,
        "placeholder": "Brand designers and creative leads",
        "default": "a general professional audience"
      },
      {
        "name": "slideCount",
        "label": "Length",
        "type": "select",
        "required": true,
        "options": [
          "short 5-10 slides",
          "medium 10-20 slides",
          "long 20+ slides"
        ],
        "default": "short 5-10 slides"
      },
      {
        "name": "density",
        "label": "Density",
        "type": "select",
        "required": true,
        "options": [
          "low density / speaker-led",
          "high density / reading-first"
        ],
        "default": "low density / speaker-led"
      }
    ],
    "context": {
      "skills": [
        {
          "path": "./SKILL.md"
        }
      ],
      "craft": [
        "typography"
      ],
      "assets": [
        "./example.html"
      ]
    },
    "pipeline": {
      "stages": [
        {
          "id": "discovery",
          "atoms": [
            "discovery-question-form"
          ]
        },
        {
          "id": "generate",
          "atoms": [
            "file-write",
            "live-artifact"
          ]
        }
      ]
    },
    "capabilities": [
      "prompt:inject",
      "fs:write"
    ],
    "category": "fundraising-pitch"
  }
}
